diamond_fifo.code:
queue = deque(["A"])
visited = {"A"}
while queue:
    node = queue.popleft()
    if node == goal: return
    for nxt in graph[node]:
        if nxt not in visited:
            visited.add(nxt)
            queue.append(nxt)

diamond_late.code:
queue = deque(["A"])
visited = set()
while queue:
    node = queue.popleft()
    if node in visited: continue
    visited.add(node)        # marked late
    if node == goal: return
    for nxt in graph[node]:
        if nxt not in visited:
            queue.append(nxt)

