steps.code:
visited = {start}
queue = deque([start])
while queue:
    cell = queue.popleft()
    for nxt in neighbours(cell):
        if nxt not in visited:
            visited.add(nxt)   # mark on append
            queue.append(nxt)

queue = deque([(start, [start])])
while queue:
    cell, path = queue.popleft()
    if cell == goal:
        return path   # first arrival = fewest steps
    for nxt in neighbours(cell):
        queue.append((nxt, path + [nxt]))
